WITH flattened AS (SELECT id, service, log_ts, latency_ms, status_code, attr_key, value FROM app_logs LATERAL VIEW EXPLODE(context) li AS attr_key, value) SELECT id, latency_ms, status_code, attr_key, COUNT(status_code) OVER (PARTITION BY service ORDER BY log_ts, id, attr_key ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) running_count_status_code, SUM(status_code) OVER (PARTITION BY service ORDER BY log_ts, id, attr_key ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) running_sum_status_code, MAX(status_code) OVER (PARTITION BY service ORDER BY log_ts, id, attr_key ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) running_max_status_code FROM flattened
